#include <iostream>
#include <string>
using namespace std;

int add(int a, int b) { return a + b; }
double add(double a, double b) { return a + b; }
string add(string a, string b) { return a + b; }

int main() {
  cout << add(5, 3) << endl;     // Calls int add(int, int)
  cout << add(5.5, 3.2) << endl; // Calls double add(double, double)
  cout << add("Hello ", "World!") << endl; // Calls string add(string, string)
  //cout << add(5, 3.14);  // Ambiguous call – would result in a compiler error
  return 0;
}
